pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 == 10);
        vm.assume(amount2 == 10);

        // First play
        vm.deal(address(this), amount1);
        c.play{value: amount1}();
        uint256 potAfterFirst = c.pot();

        // Second play
        vm.deal(address(this), amount2);
        c.play{value: amount2}();
        uint256 potAfterSecond = c.pot();

        // Invariant: pot is always equal to the total value sent minus the sum of winnings paid out.
        // Since winnings paid out = (pot before win - FEE_AMOUNT) when a win occurs, and 0 otherwise,
        // and pot before win = 10 (from single play) for first play, and for second play pot before win = potAfterFirst + 10,
        // the invariant can be checked by noting that pot is either 20 (if no win) or 10 (if win on second, first no win) or 0 (if win on first) etc.
        // But a simpler invariant: pot must be a multiple of 10 (since ticket amount is 10 and pot only changes by adding 10 or resetting to 0).
        // After a win, pot = 0 in correct version; in mutant, pot = (pot_before - FEE_AMOUNT) + 10? Actually mutant doesn't reset pot, so after a win pot = pot_before + 10 - FEE_AMOUNT = pot_before + 9.
        // So the invariant "pot is a multiple of 10" holds for correct (0 or 10 or 20) but fails for mutant after a win (e.g., pot becomes 19).
        assertTrue(potAfterFirst % 10 == 0 && potAfterSecond % 10 == 0);
    }
}

