contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint96 playerBalance) public {
        // Ensure player has enough ether for the ticket
        vm.assume(playerBalance >= 10);
        vm.deal(address(0x1234), playerBalance);
        vm.prank(address(0x1234));
        // Call play — it may revert if insufficient balance, but we catch reverts
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
        if (success) {
            // If it succeeded, then the random was 0 (win) or 1 (lose).
            // We need to condition on win. We can't read random directly, but we can check pot.
            // However, the bug is that after win pot is not reset.
            // Let's try a different approach: use time/difficulty to force win? No.
            // Instead, we note that after any play, either pot == 0 (win) or pot == 10 (lose).
            // The bug causes pot to be > 0 after a win. So we assert that pot <= 10.
            // Actually, the bug makes pot accumulate. After first win, pot becomes 10 (since pot was 0, +10, then transfer but no reset). So pot = 10. After second win, pot = 20, etc.
            // So the invariant: pot <= sum of all msg.value sent to play() since deployment.
            // But that's already tried. Let's try: after each play(), pot must be either 0 or 10 (since only one ticket per call).
            // Actually, after lose, pot = 10. After win, pot should be 0 (reference) or 10+ (bug). So rule: pot <= 10.
            uint pot = c.pot();
